// One row per G2 review, trimmed to what fits a spreadsheet.
// The pros and cons fields are where the buying objections live, so they
// stay whole; the long free-text answer is truncated instead.
const weekOf = $now.toFormat('yyyy-MM-dd');

const clip = (s, n) => {
  const v = String(s || '').replace(/\s+/g, ' ').trim();
  return v.length > n ? v.slice(0, n - 3) + '...' : v;
};

return $input.all().map((item) => {
  const r = item.json;
  // G2 does not expose a star rating on every review, so this is often blank.
  const rating = typeof r.rating === 'number' ? r.rating : '';
  return {
    json: {
      'Week of': weekOf,
      Product: r.productName || '',
      Rating: rating,
      Title: clip(r.title, 200),
      Pros: clip(r.pros, 700),
      Cons: clip(r.cons, 700),
      'Reviewer role': r.reviewerRole || '',
      'Company size': r.companySize || '',
      'Date published': String(r.datePublished || '').slice(0, 10),
      'Review link': r.reviewUrl || '',
      'Review ID': r.reviewId || '',
    },
  };
});
